#!/bin/bash
set -eu
umask 077
mkdir -p /tmp/openrx
cd /tmp/openrx
uname -a
cat /proc/cpuinfo
cat /proc/meminfo
cat /etc/os-release
base64 -d > runtime <<'OPENRX_BINARY_BASE64'

OPENRX_BINARY_BASE64
printf '%s  %s\n' '8fa3f0de97cf3df9aaecebe9deb92c3dfd8c8e7bcd18fe87e090b746e57b28ac' 'runtime' | sha256sum -c -
chmod 700 runtime
printf 'OPENRX_RUNTIME_BEGIN\n'
set +e
./runtime 2> runtime.stderr | tee runtime.jsonl
statuses=("${PIPESTATUS[@]}")
status=${statuses[0]}
capture_status=${statuses[1]}
set -e
if [ "$capture_status" -ne 0 ]; then exit "$capture_status"; fi
printf 'OPENRX_RUNTIME_END status=%s\n' "$status"
printf 'OPENRX_RUNTIME_STDERR_BEGIN\n'
cat runtime.stderr
printf 'OPENRX_RUNTIME_STDERR_END\n'
if [ "$status" -ne 0 ]; then exit "$status"; fi
base64 -d > hash <<'OPENRX_BINARY_BASE64'

OPENRX_BINARY_BASE64
printf '%s  %s\n' '61cf489ab2277477a1b5464035c21fa43c6b5e59153fe37313dbbd4ae6b4e657' 'hash' | sha256sum -c -
chmod 700 hash
printf 'OPENRX_HASH_BEGIN\n'
set +e
./hash 2> hash.stderr | tee hash.jsonl
statuses=("${PIPESTATUS[@]}")
status=${statuses[0]}
capture_status=${statuses[1]}
set -e
if [ "$capture_status" -ne 0 ]; then exit "$capture_status"; fi
printf 'OPENRX_HASH_END status=%s\n' "$status"
printf 'OPENRX_HASH_STDERR_BEGIN\n'
cat hash.stderr
printf 'OPENRX_HASH_STDERR_END\n'
if [ "$status" -ne 0 ]; then exit "$status"; fi
printf 'OPENRX_GUEST_COMPLETE\n'
